{
  "name": "pairwise_pref_loss_v1",
  "intuition": "This loss encourages the preferred sample by comparing their log probabilities while incorporating a penalty based on the difference in cost gap, promoting preference consistency and robust ranking. Using logsigmoid on the difference captures the pairwise preference dynamics, and weighting ensures meaningful influence of cost differences.",
  "pseudocode": "loss = -mean(logsigmoid((log_prob_w - log_prob_l) * weight + alpha * cost_gap))",
