    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    cost_gap = batch.get(\"cost_gap\", zeros_like(log_prob_w))\n    diff = sub(log_prob_w, log_prob_l)\n    weighted_diff = add(mul(diff, weight), mul(alpha, cost_gap))\n    loss = -mean(logsigmoid(weighted_diff))\n    return loss"
